(4714282, 680657, 82461, '<td valign="top">wow.... scary shot....</td>', 'wow.... scary shot....', '2008-05-21 07:49:25.000000', NULL, 1),
(4714322, 680383, 64670, '<td valign="top">Truly lovely.</td>', 'Truly lovely.', '2008-05-21 08:09:15.000000', NULL, 1),
