(4714326, 680227, 39850, '<td valign="top">Beautifully captured.  Well done to get the light as well - especially for this Challenge, can''t help wondering about emphasizing that by cropping out the left side - but then you''d lose the good reflections there.. who knows.</td>', 'Beautifully captured.  Well done to get the light as well - especially for this Challenge, can''t help wondering about emphasizing that by cropping out the left side - but then you''d lose the good reflections there.. who knows.', '2008-05-21 08:11:21.000000', NULL, 1),
(4714327, 680537, 64670, '<td valign="top">Fabulous!</td>', 'Fabulous!', '2008-05-21 08:12:12.000000', NULL, 1),
(4714329, 680292, 39850, '<td valign="top">Very nice and good thinking with the moonlight.  Maybe a little more off the top to emphasize the shadows and bring that front deck into play more - looks like a nice place to sit.</td>', 'Very nice and good thinking with the moonlight.  Maybe a little more off the top to emphasize the shadows and bring that front deck into play more - looks like a nice place to sit.', '2008-05-21 08:13:00.000000', NULL, 1),
(4714334, 679454, 38032, '<td valign="top">wow- very telling image and great use of light. 8</td>', 'wow- very telling image and great use of light. 8', '2008-05-21 08:15:07.000000', NULL, 1),
