(4714349, 679929, 3569, '<td valign="top">excellent</td>', 'excellent', '2008-05-21 08:19:23.000000', NULL, 1),
(4714350, 680036, 38032, '<td valign="top">Appealing and quaint - definitely has a nice calm mood to it ... where''s my tea? :)<br/>Picky points: The horizon in the distance near the top makes a recrop a good idea (crop to eliminate the sky).  Also- I actually have that same plastic house in my back yard but I don''t think it fits well in the otherwise natural elements of this shot. The composition is good though. 6</td>', 'Appealing and quaint - definitely has a nice calm mood to it ... where''s my tea? :)Picky points: The horizon in the distance near the top makes a recrop a good idea (crop to eliminate the sky).  Also- I actually have that same plastic house in my back yard but I don''t think it fits well in the otherwise natural elements of this shot. The composition is good though. 6', '2008-05-21 08:19:53.000000', NULL, 1),
(4714357, 680469, 3569, '<td valign="top">nice portrait</td>', 'nice portrait', '2008-05-21 08:21:33.000000', NULL, 1),
