(4715511, 679994, 14867, '<td valign="top">Very well done, and really using the dappled light as a major element of the composition. Not much to improve. With more editing, you could have lightened her left eye, but with basic editing you can''t do better...</td>', 'Very well done, and really using the dappled light as a major element of the composition. Not much to improve. With more editing, you could have lightened her left eye, but with basic editing you can''t do better...', '2008-05-21 15:53:30.000000', NULL, 1),
(4715517, 680522, 14867, '<td valign="top">Good idea, though in need of contrast and saturation</td>', 'Good idea, though in need of contrast and saturation', '2008-05-21 15:54:52.000000', NULL, 1),
(4715525, 680383, 14867, '<td valign="top">Not The usual image of Le Louvre, for sure...Interesting by its light, less  by its composition, a bit complicated for my taste.</td>', 'Not The usual image of Le Louvre, for sure...Interesting by its light, less  by its composition, a bit complicated for my taste.', '2008-05-21 16:01:19.000000', NULL, 1),
(4715527, 680448, 59144, '<td valign="top">It would be nice to see more light...to have the light stand out more</td>', 'It would be nice to see more light...to have the light stand out more', '2008-05-21 16:01:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4715528, 680192, 59144, '<td valign="top">beautiful..I like the use of the dappled light on the white</td>', 'beautiful..I like the use of the dappled light on the white', '2008-05-21 16:02:25.000000', NULL, 1),
(4715531, 680215, 59144, '<td valign="top">gorgeous catch.  Needs to be more dapply.</td>', 'gorgeous catch.  Needs to be more dapply.', '2008-05-21 16:04:21.000000', NULL, 1),
(4715532, 680176, 14867, '<td valign="top">The B&amp;W is good, the light is very good, the composition...wich composition?<br/> <br/>Something very strong is not needed with this kind of image, but at least one line leading the eye into the image was necessary IMO. Globally, above average though.</td>', 'The B&W is good, the light is very good, the composition...wich composition? Something very strong is not needed with this kind of image, but at least one line leading the eye into the image was necessary IMO. Globally, above average though.', '2008-05-21 16:04:49.000000', NULL, 1),
(4715536, 680215, 14867, '<td valign="top">Beautiful light, a little mysterious in the background, with a simple, well balanced composition.</td>', 'Beautiful light, a little mysterious in the background, with a simple, well balanced composition.', '2008-05-21 16:07:31.000000', NULL, 1),
(4715537, 680475, 14867, '<td valign="top">Superb - nothing more to add.</td>', 'Superb - nothing more to add.', '2008-05-21 16:08:50.000000', NULL, 1),
(4715556, 679776, 59144, '<td valign="top">more dapply than light and shadow.  I like the composition though. Very nice</td>', 'more dapply than light and shadow.  I like the composition though. Very nice', '2008-05-21 16:27:00.000000', NULL, 1),
(4715559, 680640, 59144, '<td valign="top">Nice.</td>', 'Nice.', '2008-05-21 16:27:53.000000', NULL, 1),
(4715560, 680460, 59144, '<td valign="top">Cutie!  Nice dappled light.  This is a hard one</td>', 'Cutie!  Nice dappled light.  This is a hard one', '2008-05-21 16:28:25.000000', NULL, 1),
(4715562, 680410, 5746, '<td valign="top">Looks to me a bit blown up but maybe it was your intention to make it high key. There is only a signe of dappled light here. However I like the composition.</td>', 'Looks to me a bit blown up but maybe it was your intention to make it high key. There is only a signe of dappled light here. However I like the composition.', '2008-05-21 16:30:34.000000', NULL, 1),
(4715563, 679158, 59144, '<td valign="top">I guess I think dappled light as different from shadows, but maybe I am wrong. Love the colors though</td>', 'I guess I think dappled light as different from shadows, but maybe I am wrong. Love the colors though', '2008-05-21 16:31:04.000000', NULL, 1),
(4715569, 680227, 59144, '<td valign="top">Is this in the Philippines?</td>', 'Is this in the Philippines?', '2008-05-21 16:34:29.000000', NULL, 1),
(4715575, 679822, 59144, '<td valign="top">Bright and vibrant...</td>', 'Bright and vibrant...', '2008-05-21 16:37:48.000000', NULL, 1),
(4715577, 680131, 59144, '<td valign="top">Awesome colors, awesome composition and awesome dappling.  The first real one I have seen so far.</td>', 'Awesome colors, awesome composition and awesome dappling.  The first real one I have seen so far.', '2008-05-21 16:39:36.000000', NULL, 1),
(4715579, 679646, 59144, '<td valign="top">This is more bokeh than dappled</td>', 'This is more bokeh than dappled', '2008-05-21 16:40:15.000000', NULL, 1),
(4715581, 679877, 5746, '<td valign="top">Very nice, subtle colour scheme. It''s not very DPC, so it may suffer. Irises are shifted a bit to the center from the golden point. Taking the title into consideration more country or more road would''ve make the message more clear.</td>', 'Very nice, subtle colour scheme. It''s not very DPC, so it may suffer. Irises are shifted a bit to the center from the golden point. Taking the title into consideration more country or more road would''ve make the message more clear.', '2008-05-21 16:41:10.000000', NULL, 1),
(4715584, 680571, 5746, '<td valign="top">I don''t get the title, but the dappled light is obviously the subject :)</td>', 'I don''t get the title, but the dappled light is obviously the subject :)', '2008-05-21 16:42:23.000000', NULL, 1),
(4715585, 680079, 59144, '<td valign="top">Too bright a light source...not enough dapple</td>', 'Too bright a light source...not enough dapple', '2008-05-21 16:42:27.000000', NULL, 1),
(4715587, 679674, 59144, '<td valign="top">Nice.  I like it</td>', 'Nice.  I like it', '2008-05-21 16:42:59.000000', NULL, 1),
(4715590, 679760, 5746, '<td valign="top">Looks a bit oveersharpened, however it may be my LCD or the fact the leaves are still young and small.Beautifuly captured mosaic of light on the road, crisp colours a strong contrast. I like it.</td>', 'Looks a bit oveersharpened, however it may be my LCD or the fact the leaves are still young and small.Beautifuly captured mosaic of light on the road, crisp colours a strong contrast. I like it.', '2008-05-21 16:44:01.000000', NULL, 1),
(4715598, 679674, 5746, '<td valign="top">I''m loosing some details here. The shadows are very soft, probably it''s the cause. Interesting place. I would love to see it in colour.</td>', 'I''m loosing some details here. The shadows are very soft, probably it''s the cause. Interesting place. I would love to see it in colour.', '2008-05-21 16:47:58.000000', NULL, 1),
(4715605, 680412, 5746, '<td valign="top">Looks a bit oersharpened and oversaturated, but it may be my LCD. The water looks like curtain. I like green reflections in the waterfall.</td>', 'Looks a bit oersharpened and oversaturated, but it may be my LCD. The water looks like curtain. I like green reflections in the waterfall.', '2008-05-21 16:54:51.000000', NULL, 1),
(4715606, 679888, 53416, '<td valign="top">Great colour and vibrant.  Would like to see more of the building though.</td>', 'Great colour and vibrant.  Would like to see more of the building though.', '2008-05-21 16:55:42.000000', NULL, 1),
(4715608, 679416, 53416, '<td valign="top">Not very dappled, but is sharp with nice details.I think the strong lighting works quite well too.</td>', 'Not very dappled, but is sharp with nice details.I think the strong lighting works quite well too.', '2008-05-21 16:57:00.000000', NULL, 1),
(4715611, 680478, 53416, '<td valign="top">Great colour with a nice blurry background.  Would like more of the plants in focus though.</td>', 'Great colour with a nice blurry background.  Would like more of the plants in focus though.', '2008-05-21 16:58:47.000000', NULL, 1),
(4715614, 680036, 53416, '<td valign="top">I think the big white basket mid left is a bit distracting from the sunject.  Otherwise quite nice.</td>', 'I think the big white basket mid left is a bit distracting from the sunject.  Otherwise quite nice.', '2008-05-21 17:00:05.000000', NULL, 1),
(4715617, 680532, 5746, '<td valign="top">Looks more like a backlight to me, than dappled light, but it''s me beeing just picky. Great detail, nice, natural colours, elegant composition. Very good shot.</td>', 'Looks more like a backlight to me, than dappled light, but it''s me beeing just picky. Great detail, nice, natural colours, elegant composition. Very good shot.', '2008-05-21 17:01:21.000000', NULL, 1),
(4715619, 679522, 53416, '<td valign="top">I like how the dappled light is highlighting the flowers.</td>', 'I like how the dappled light is highlighting the flowers.', '2008-05-21 17:02:27.000000', NULL, 1),
(4715620, 680493, 53416, '<td valign="top">Great light and contrast.  Thought provoking too.  Well done.</td>', 'Great light and contrast.  Thought provoking too.  Well done.', '2008-05-21 17:03:10.000000', NULL, 1),
(4715621, 680036, 5746, '<td valign="top">I envy Emma :) It looks overexposed and a bit blurry. Looks like you focused on the leaves behind Emma, than herself. This picture has potential, however I would''ve tried different angle to avoid the children house, as it looks plastic and doesn''t add to the picture.</td>', 'I envy Emma :) It looks overexposed and a bit blurry. Looks like you focused on the leaves behind Emma, than herself. This picture has potential, however I would''ve tried different angle to avoid the children house, as it looks plastic and doesn''t add to the picture.', '2008-05-21 17:04:07.000000', NULL, 1),
(4715622, 680332, 53416, '<td valign="top">Interesting subject - I hope this was staged!  Nice dappled background, but the foot is a bit overblown...</td>', 'Interesting subject - I hope this was staged!  Nice dappled background, but the foot is a bit overblown...', '2008-05-21 17:04:22.000000', NULL, 1),
(4715624, 680292, 53416, '<td valign="top">A nice take on the challenge, using moonlight and not sunlight.  The deep blue sky works really well with the pale grey buiding.  Nice.</td>', 'A nice take on the challenge, using moonlight and not sunlight.  The deep blue sky works really well with the pale grey buiding.  Nice.', '2008-05-21 17:05:31.000000', NULL, 1),
(4715626, 680460, 53416, '<td valign="top">Nice depth of field, but the horizon looks a bit wonky.</td>', 'Nice depth of field, but the horizon looks a bit wonky.', '2008-05-21 17:06:18.000000', NULL, 1),
(4715629, 680134, 53416, '<td valign="top">I love the lighting here.  The textures and detail work nicely too.</td>', 'I love the lighting here.  The textures and detail work nicely too.', '2008-05-21 17:07:01.000000', NULL, 1),
(4715632, 679158, 53416, '<td valign="top">I''m not sure what this is, but it''s very pretty!  Could do with being fully central, or more off set - to me it just looks a bit misaligned and a little wonky.</td>', 'I''m not sure what this is, but it''s very pretty!  Could do with being fully central, or more off set - to me it just looks a bit misaligned and a little wonky.', '2008-05-21 17:08:24.000000', NULL, 1),
(4715637, 680382, 53416, '<td valign="top">I wish the dappling was stronger, so that more of the subject was highlighted.</td>', 'I wish the dappling was stronger, so that more of the subject was highlighted.', '2008-05-21 17:09:18.000000', NULL, 1),
(4715639, 679244, 53416, '<td valign="top">Interseting perspective, and very unique - but it doesn''t really work for me.</td>', 'Interseting perspective, and very unique - but it doesn''t really work for me.', '2008-05-21 17:09:59.000000', NULL, 1),
(4715640, 680176, 5746, '<td valign="top">Looks like a piece of graphic. The composition would be perfect for a textile :) I like B&amp;W choice for this one. It''s excellent technically. Very elegant. I wonder if yo had more smaller leaves in frame, as they look more interesting (making the composition more interesting I mean, than big flat areas of big leaves).</td>', 'Looks like a piece of graphic. The composition would be perfect for a textile :) I like B&W choice for this one. It''s excellent technically. Very elegant. I wonder if yo had more smaller leaves in frame, as they look more interesting (making the composition more interesting I mean, than big flat areas of big leaves).', '2008-05-21 17:10:16.000000', NULL, 1),
(4715641, 679445, 53416, '<td valign="top">Nice composition and interesting dappling.  I''m not too keen on the background (shed?) though.</td>', 'Nice composition and interesting dappling.  I''m not too keen on the background (shed?) though.', '2008-05-21 17:10:58.000000', NULL, 1),
(4715644, 680383, 53416, '<td valign="top">I really like this!  The lighting is excellent - I love the different texture of the large paving next to the small.  Well done!</td>', 'I really like this!  The lighting is excellent - I love the different texture of the large paving next to the small.  Well done!', '2008-05-21 17:12:09.000000', NULL, 1),
(4715646, 680657, 5746, '<td valign="top">I like the composition here and the limited colour scheme. I like they way you leave something for the viewer imagination. That makes a difference between a good photo or a postcard. I can see a bit of grain in the upper part of the image, but only under a certain angle so it may be my LCD. Very, very fresh idea.</td>', 'I like the composition here and the limited colour scheme. I like they way you leave something for the viewer imagination. That makes a difference between a good photo or a postcard. I can see a bit of grain in the upper part of the image, but only under a certain angle so it may be my LCD. Very, very fresh idea.', '2008-05-21 17:12:23.000000', NULL, 1),
(4715647, 680176, 53416, '<td valign="top">Great contrast and detail.</td>', 'Great contrast and detail.', '2008-05-21 17:12:35.000000', NULL, 1),
(4715648, 679161, 53416, '<td valign="top">Awww, aren''t they cute!  Wish the scene was more dappled though.....</td>', 'Awww, aren''t they cute!  Wish the scene was more dappled though.....', '2008-05-21 17:13:38.000000', NULL, 1),
(4715650, 680137, 53416, '<td valign="top">Interesting lighting, and I love the colour and contrast between the subject and background.  I''m not quite sure what it is, but the composition doesn''t entirely work for me though.....</td>', 'Interesting lighting, and I love the colour and contrast between the subject and background.  I''m not quite sure what it is, but the composition doesn''t entirely work for me though.....', '2008-05-21 17:15:19.000000', NULL, 1),
(4715658, 679994, 53416, '<td valign="top">The harsh lighting creates a very strong and quite unique portrait.  THAT eye is just a bit too unnerving though!<br/> <br/>Scary!!!</td>', 'The harsh lighting creates a very strong and quite unique portrait.  THAT eye is just a bit too unnerving though! Scary!!!', '2008-05-21 17:16:53.000000', NULL, 1),
(4715662, 680475, 53416, '<td valign="top">A great photograph!  I love the colours and the lighting.  The fluffy white water contrast nicely with the sharp trees.  Very nice!</td>', 'A great photograph!  I love the colours and the lighting.  The fluffy white water contrast nicely with the sharp trees.  Very nice!', '2008-05-21 17:18:31.000000', NULL, 1),
(4715663, 680412, 53416, '<td valign="top">Great colour and detail.</td>', 'Great colour and detail.', '2008-05-21 17:18:56.000000', NULL, 1),
(4715664, 679522, 55782, '<td valign="top">how sweet!  nice color.</td>', 'how sweet!  nice color.', '2008-05-21 17:19:09.000000', NULL, 1),
(4715665, 680503, 5746, '<td valign="top">The colours look a bit blown up. Also the lion is a bit soft. Maybe it was too early to catch nice, rich and warm colours of the lion. Evening light is far more flattering usually. I like cat expression.</td>', 'The colours look a bit blown up. Also the lion is a bit soft. Maybe it was too early to catch nice, rich and warm colours of the lion. Evening light is far more flattering usually. I like cat expression.', '2008-05-21 17:19:12.000000', NULL, 1),
(4715667, 680620, 55782, '<td valign="top">love the texture</td>', 'love the texture', '2008-05-21 17:19:21.000000', NULL, 1),
(4715669, 680292, 55782, '<td valign="top">gorgeous sky</td>', 'gorgeous sky', '2008-05-21 17:19:39.000000', NULL, 1),
(4715671, 680657, 53416, '<td valign="top">Interesting perspective and composition - but I wish I could see more of its head!</td>', 'Interesting perspective and composition - but I wish I could see more of its head!', '2008-05-21 17:19:55.000000', NULL, 1),
(4715672, 680149, 55782, '<td valign="top">love this in Black and White</td>', 'love this in Black and White', '2008-05-21 17:20:34.000000', NULL, 1),
(4715675, 679725, 5746, '<td valign="top">Dappled light is a bit subtle here (I guess you wanted to catch it on the surface of the water). The bridge is very dark. If you turned a bit to the left and made people a main subject it could help a lot. I like the colour of the water.</td>', 'Dappled light is a bit subtle here (I guess you wanted to catch it on the surface of the water). The bridge is very dark. If you turned a bit to the left and made people a main subject it could help a lot. I like the colour of the water.', '2008-05-21 17:21:18.000000', NULL, 1),
(4715676, 680503, 53416, '<td valign="top">A nice capture, with good lighting.  That leaf infront of his face is a bit distracting though.</td>', 'A nice capture, with good lighting.  That leaf infront of his face is a bit distracting though.', '2008-05-21 17:21:19.000000', NULL, 1),
(4715677, 680142, 55782, '<td valign="top">sweet</td>', 'sweet', '2008-05-21 17:21:19.000000', NULL, 1),
(4715679, 680383, 55782, '<td valign="top">love this.  my favorite so far in this challenge</td>', 'love this.  my favorite so far in this challenge', '2008-05-21 17:21:36.000000', NULL, 1),
(4715680, 680635, 53416, '<td valign="top">Nice composition, with good detail and nice dappling!  Well done.</td>', 'Nice composition, with good detail and nice dappling!  Well done.', '2008-05-21 17:21:59.000000', NULL, 1),
(4715681, 680640, 55782, '<td valign="top">beautiful color</td>', 'beautiful color', '2008-05-21 17:22:01.000000', NULL, 1),
(4715683, 680494, 5746, '<td valign="top">I''m not sure it is a dappled light, but I like the abstract feel of this picture. Looks like an unusual galaxy. The colours are also nice.</td>', 'I''m not sure it is a dappled light, but I like the abstract feel of this picture. Looks like an unusual galaxy. The colours are also nice.', '2008-05-21 17:22:28.000000', NULL, 1),
(4715684, 680433, 55782, '<td valign="top">love it, love it.</td>', 'love it, love it.', '2008-05-21 17:22:36.000000', NULL, 1),
(4715688, 680475, 55782, '<td valign="top">great exposure.  brilliant color. dappled light?  hmmm.</td>', 'great exposure.  brilliant color. dappled light?  hmmm.', '2008-05-21 17:23:57.000000', NULL, 1),
(4715689, 680457, 5746, '<td valign="top">The picture looks a bit flat. Deeper depth of field could help give it more clarity. Or maybe it is contrast? You could go back and try it a bit later during a day, when the shadows are more intense and longer.</td>', 'The picture looks a bit flat. Deeper depth of field could help give it more clarity. Or maybe it is contrast? You could go back and try it a bit later during a day, when the shadows are more intense and longer.', '2008-05-21 17:24:10.000000', NULL, 1),
(4715690, 680096, 53416, '<td valign="top">Good dappling and nicely composed.</td>', 'Good dappling and nicely composed.', '2008-05-21 17:25:17.000000', NULL, 1),
(4715693, 680018, 53416, '<td valign="top">Makes me wonder what he''s gazing at..?  Nice dappled background too.</td>', 'Makes me wonder what he''s gazing at..?  Nice dappled background too.', '2008-05-21 17:26:08.000000', NULL, 1),
(4715696, 680609, 53416, '<td valign="top">Great colour and detail.  Nice dappling too.</td>', 'Great colour and detail.  Nice dappling too.', '2008-05-21 17:26:41.000000', NULL, 1),
(4715700, 679776, 53416, '<td valign="top">Nice lighting and contrast, but lacks a real focal point.</td>', 'Nice lighting and contrast, but lacks a real focal point.', '2008-05-21 17:27:22.000000', NULL, 1),
(4715704, 680692, 53416, '<td valign="top">Lacks real focus.  Would have been better suited to last weeks sun in the picture challenge!</td>', 'Lacks real focus.  Would have been better suited to last weeks sun in the picture challenge!', '2008-05-21 17:28:38.000000', NULL, 1),
(4715705, 679259, 53416, '<td valign="top">Great depth of field, sharp and with good colour and contrast.  Well done!</td>', 'Great depth of field, sharp and with good colour and contrast.  Well done!', '2008-05-21 17:29:28.000000', NULL, 1),
(4715707, 679914, 53416, '<td valign="top">Nice depth of field and composition.</td>', 'Nice depth of field and composition.', '2008-05-21 17:29:56.000000', NULL, 1),
(4715832, 680478, 5746, '<td valign="top">Greens lost their colour somehow, or maybe it was your choice to make the purple tulips to stand out more. BTW beautiful colour.</td>', 'Greens lost their colour somehow, or maybe it was your choice to make the purple tulips to stand out more. BTW beautiful colour.', '2008-05-21 18:20:02.000000', NULL, 1),
(4715836, 680460, 5746, '<td valign="top">The picture looks soft. Could be your intention, since it is a child portrait. Nice, delicate colours. Cropping is a bit tight. More breathing space, could add to the picture. The border is disturbing a bit also.</td>', 'The picture looks soft. Could be your intention, since it is a child portrait. Nice, delicate colours. Cropping is a bit tight. More breathing space, could add to the picture. The border is disturbing a bit also.', '2008-05-21 18:22:16.000000', NULL, 1),
(4715840, 678783, 5746, '<td valign="top">Nice complementary colours. I like the idea. No idea what it is, but reminds me of an Earth pictures made from space.</td>', 'Nice complementary colours. I like the idea. No idea what it is, but reminds me of an Earth pictures made from space.', '2008-05-21 18:24:55.000000', NULL, 1),
(4715857, 680142, 5746, '<td valign="top">The shadow color shift is a bit yellow. However, it''s visible only under a specific angle, so it could be my laptop LCD. Nice atmosphere here. Beautiful portrait of the beautiful child. The lace gives it romantic feel.</td>', 'The shadow color shift is a bit yellow. However, it''s visible only under a specific angle, so it could be my laptop LCD. Nice atmosphere here. Beautiful portrait of the beautiful child. The lace gives it romantic feel.', '2008-05-21 18:33:11.000000', NULL, 1),
(4715860, 680475, 5746, '<td valign="top">So juicy. Almost oersaturated. Good try on long exposure. Like from the child fairytale.</td>', 'So juicy. Almost oersaturated. Good try on long exposure. Like from the child fairytale.', '2008-05-21 18:34:30.000000', NULL, 1),
(4715878, 679822, 5746, '<td valign="top">Great colours, but the main subject is still soft. It''s like only the edge of the closest petals are in focus. The light probably was quite harsh, as edges are a bit overexposed. It makes the dappled light barely visible. Beautiful flowers, they just need more patience I guess.</td>', 'Great colours, but the main subject is still soft. It''s like only the edge of the closest petals are in focus. The light probably was quite harsh, as edges are a bit overexposed. It makes the dappled light barely visible. Beautiful flowers, they just need more patience I guess.', '2008-05-21 18:41:07.000000', NULL, 1),
(4715884, 680018, 5746, '<td valign="top">Maybe these are my eyes, but it looks like his hair is in focus. Try to focus on human eyes. He is such a lovely model. The dappled light is significant element of the composition.</td>', 'Maybe these are my eyes, but it looks like his hair is in focus. Try to focus on human eyes. He is such a lovely model. The dappled light is significant element of the composition.', '2008-05-21 18:43:45.000000', NULL, 1),
(4715896, 680134, 5746, '<td valign="top">Wow, impressive tree. I know you wanted to include dappled light in this picture, but I would like to see some outtakes after the challenge, where citizen is more visible (closer probably). I''m sure it has interesting texture. Now the eye is drawn to the branches and the building behind.</td>', 'Wow, impressive tree. I know you wanted to include dappled light in this picture, but I would like to see some outtakes after the challenge, where citizen is more visible (closer probably). I''m sure it has interesting texture. Now the eye is drawn to the branches and the building behind.', '2008-05-21 18:49:32.000000', NULL, 1),
(4715924, 679524, 5746, '<td valign="top">Dappled light is very subtle here. I find the white area a bit disturbing. It takes attention from the eyes of the model IMHO. Also the angle of the shot makes his jaws heavy, but maybe you wanted to achieve such effect. Nice idea. Brings Robin Hood to my mind :)</td>', 'Dappled light is very subtle here. I find the white area a bit disturbing. It takes attention from the eyes of the model IMHO. Also the angle of the shot makes his jaws heavy, but maybe you wanted to achieve such effect. Nice idea. Brings Robin Hood to my mind :)', '2008-05-21 18:56:40.000000', NULL, 1),
(4715935, 680625, 88613, '<td valign="top">Amazing shot! I wish it was a little sharper but still a great capture!</td>', 'Amazing shot! I wish it was a little sharper but still a great capture!', '2008-05-21 18:59:30.000000', NULL, 1),
(4715949, 680441, 5746, '<td valign="top">Definately you caught the dappled light here. I just have an impression that it is either too close or to far to make the composition eye catching. It''s just a not very interesting object centered in the frame. Maybe a strand of grass as a main subject could be a better choice, leaving the dappled light an interesting background? Or a closer shot of an object? Just to leave it something to viewer imagination.</td>', 'Definately you caught the dappled light here. I just have an impression that it is either too close or to far to make the composition eye catching. It''s just a not very interesting object centered in the frame. Maybe a strand of grass as a main subject could be a better choice, leaving the dappled light an interesting background? Or a closer shot of an object? Just to leave it something to viewer imagination.', '2008-05-21 19:04:07.000000', NULL, 1),
(4715952, 680380, 89669, '<td valign="top">Very nice composition.</td>', 'Very nice composition.', '2008-05-21 19:04:41.000000', NULL, 1),
(4715957, 679033, 88613, '<td valign="top">Nice shot! I think it would have looked cool with a perspective closer to the ground, but thats my personal preference. I like it!</td>', 'Nice shot! I think it would have looked cool with a perspective closer to the ground, but thats my personal preference. I like it!', '2008-05-21 19:05:47.000000', NULL, 1),
(4715958, 679664, 89669, '<td valign="top">It''s a little to dark for my taste, but I like the composition.</td>', 'It''s a little to dark for my taste, but I like the composition.', '2008-05-21 19:05:49.000000', NULL, 1),
(4715964, 680382, 5746, '<td valign="top">The model is great. Dappled light is very subtle. Unfortunately there is nothing interesting happening in the sky. I wish you took a different angle to get rid of a grey and oerexposed sky. The idea is very good. I like the colours and very natural pose of the model. Just the sky...</td>', 'The model is great. Dappled light is very subtle. Unfortunately there is nothing interesting happening in the sky. I wish you took a different angle to get rid of a grey and oerexposed sky. The idea is very good. I like the colours and very natural pose of the model. Just the sky...', '2008-05-21 19:06:58.000000', NULL, 1),
(4715968, 680546, 89669, '<td valign="top">It seems to lack overall sharpness. The flowers mid right are a litle over exposed.</td>', 'It seems to lack overall sharpness. The flowers mid right are a litle over exposed.', '2008-05-21 19:07:51.000000', NULL, 1),
(4715972, 680641, 5746, '<td valign="top">Closer... I wish it was closer. Lovely reflections. They make heart shape. The background looks almost silver. The leave however is overburdened by the reflections, that''s why the first thought was to come closer :)</td>', 'Closer... I wish it was closer. Lovely reflections. They make heart shape. The background looks almost silver. The leave however is overburdened by the reflections, that''s why the first thought was to come closer :)', '2008-05-21 19:09:04.000000', NULL, 1),
(4715980, 680537, 89669, '<td valign="top">It is a little to busy for me. Perhaps a different angle would help. I think it has potential though.</td>', 'It is a little to busy for me. Perhaps a different angle would help. I think it has potential though.', '2008-05-21 19:11:08.000000', NULL, 1),
