(4717430, 680479, 39679, '<td valign="top">Very cute and well shot.</td>', 'Very cute and well shot.', '2008-05-22 12:50:47.000000', NULL, 1),
(4717435, 680546, 39679, '<td valign="top">Nice shot...the colors are very vivid.  If you could have "managed" a less cluttered background, the flowers would have really stood out.</td>', 'Nice shot...the colors are very vivid.  If you could have "managed" a less cluttered background, the flowers would have really stood out.', '2008-05-22 12:52:04.000000', NULL, 1),
(4717436, 679460, 92383, '<td valign="top">Wow - Looks exactly as I remember a part in Pink Floyd''s The Wall.  Just after the child says, "Look Mommy there''s a little plane up in the sky".  Then this very cat runs after a dove.  A little spooky. Dappled effect enhances your image rather than complicating it as I''ve seen in so many others.  Subdued.</td>', 'Wow - Looks exactly as I remember a part in Pink Floyd''s The Wall.  Just after the child says, "Look Mommy there''s a little plane up in the sky".  Then this very cat runs after a dove.  A little spooky. Dappled effect enhances your image rather than complicating it as I''ve seen in so many others.  Subdued.', '2008-05-22 12:52:09.000000', NULL, 1),
(4717439, 680532, 39679, '<td valign="top">I''ve always like shots like this (backlit leaves) and you''ve done a great job of making the subject stand out.</td>', 'I''ve always like shots like this (backlit leaves) and you''ve done a great job of making the subject stand out.', '2008-05-22 12:53:00.000000', NULL, 1),
