(4719165, 679697, 33769, '<td valign="top">great use of negative space; nice choice of colors, beautiful use of the lighting :)</td>', 'great use of negative space; nice choice of colors, beautiful use of the lighting :)', '2008-05-23 08:12:56.000000', NULL, 1),
(4719168, 680493, 33769, '<td valign="top">very nice capture of light and shadow; focus is sharp, and the dappled light works very nicely in this B&amp;W great job; the negative space created here is also very interesting to look at as well  very artistic!</td>', 'very nice capture of light and shadow; focus is sharp, and the dappled light works very nicely in this B&W great job; the negative space created here is also very interesting to look at as well  very artistic!', '2008-05-23 08:14:50.000000', NULL, 1),
(4719169, 680475, 33769, '<td valign="top">Lovely capture, soft and beautiful; its amazing to think places like this are really out there!</td>', 'Lovely capture, soft and beautiful; its amazing to think places like this are really out there!', '2008-05-23 08:15:57.000000', NULL, 1),
(4719170, 679374, 33769, '<td valign="top">really nice capture; i love your DOF here and the details of the skin and bark....  really nice color range (did you hold a card behind the bark or is this inside?- it''ll be interesting to find out!!)  nice use of light here to highlight features and the shadows are subtle but lovely as well! beautiful capture :)</td>', 'really nice capture; i love your DOF here and the details of the skin and bark....  really nice color range (did you hold a card behind the bark or is this inside?- it''ll be interesting to find out!!)  nice use of light here to highlight features and the shadows are subtle but lovely as well! beautiful capture :)', '2008-05-23 08:17:36.000000', NULL, 1),
(4719171, 680142, 33769, '<td valign="top">wow-what lovely detail, and a very beautiful subject ;)  very nice profile!</td>', 'wow-what lovely detail, and a very beautiful subject ;)  very nice profile!', '2008-05-23 08:18:32.000000', NULL, 1),
(4719172, 680137, 33769, '<td valign="top">underwater camera?!? I really look forward to finding out more about this one; this is really neat- beautiful  play of light and shadow interesting shapes - I really want to experiment with underwater photography soon -this is inspirational :)</td>', 'underwater camera?!? I really look forward to finding out more about this one; this is really neat- beautiful  play of light and shadow interesting shapes - I really want to experiment with underwater photography soon -this is inspirational :)', '2008-05-23 08:21:13.000000', NULL, 1),
(4719174, 680412, 33769, '<td valign="top">whimsical, beautiful; surreal... i almost expect to see faries flittering over the water any second... beautiful use of dapled light, the subtlty works nicely here! :) and the reflections and colors are just breath-taking !</td>', 'whimsical, beautiful; surreal... i almost expect to see faries flittering over the water any second... beautiful use of dapled light, the subtlty works nicely here! :) and the reflections and colors are just breath-taking !', '2008-05-23 08:22:30.000000', NULL, 1),
(4719189, 680621, 73063, '<td valign="top">Like the strong composition and the shades of blue, hope this does well.</td>', 'Like the strong composition and the shades of blue, hope this does well.', '2008-05-23 08:55:37.000000', NULL, 1),
