(4719527, 679674, 89426, '<td valign="top">The land is a little dull for a good picture</td>', 'The land is a little dull for a good picture', '2008-05-23 11:08:48.000000', NULL, 1),
(4719528, 680523, 89431, '<td valign="top">I like the subject and the cropping and the way you changed the generic flower picture. Way to change it up!</td>', 'I like the subject and the cropping and the way you changed the generic flower picture. Way to change it up!', '2008-05-23 11:08:55.000000', NULL, 1),
(4719530, 680149, 89426, '<td valign="top">Nice capture of dappled lighting</td>', 'Nice capture of dappled lighting', '2008-05-23 11:09:16.000000', NULL, 1),
(4719531, 679878, 89431, '<td valign="top">Really cool lighting and the black &amp; white was a good choice here. Could use more contrast.</td>', 'Really cool lighting and the black & white was a good choice here. Could use more contrast.', '2008-05-23 11:09:30.000000', NULL, 1),
(4719535, 679551, 89431, '<td valign="top">The colors &amp; compo. are beautiful but the quality seems low.</td>', 'The colors & compo. are beautiful but the quality seems low.', '2008-05-23 11:11:20.000000', NULL, 1),
(4719536, 680692, 89426, '<td valign="top">A little blury, but nice idea and picture overall</td>', 'A little blury, but nice idea and picture overall', '2008-05-23 11:11:21.000000', NULL, 1),
(4719539, 680679, 89426, '<td valign="top">I think a different angle would have made a nicer photo</td>', 'I think a different angle would have made a nicer photo', '2008-05-23 11:12:13.000000', NULL, 1),
