(4719542, 680620, 89427, '<td valign="top">i love the black and white and the lighting great job</td>', 'i love the black and white and the lighting great job', '2008-05-23 11:12:40.000000', NULL, 1),
(4719544, 680137, 89427, '<td valign="top">great idea and colors for an underwater shot</td>', 'great idea and colors for an underwater shot', '2008-05-23 11:13:02.000000', NULL, 1),
(4719546, 680640, 89426, '<td valign="top">A very pretty picture</td>', 'A very pretty picture', '2008-05-23 11:13:06.000000', NULL, 1),
(4719547, 680620, 89431, '<td valign="top">Nice contrast and concept... not so dappled though yea?</td>', 'Nice contrast and concept... not so dappled though yea?', '2008-05-23 11:13:09.000000', NULL, 1),
(4719548, 680082, 89427, '<td valign="top">great angle and composition</td>', 'great angle and composition', '2008-05-23 11:13:23.000000', NULL, 1),
(4719549, 679033, 89426, '<td valign="top">Nice idea and capture</td>', 'Nice idea and capture', '2008-05-23 11:13:29.000000', NULL, 1),
(4719550, 679914, 89431, '<td valign="top">With all that softness its hard to make out where the dappled part is.</td>', 'With all that softness its hard to make out where the dappled part is.', '2008-05-23 11:13:38.000000', NULL, 1),
(4719551, 680332, 89427, '<td valign="top">strange concept</td>', 'strange concept', '2008-05-23 11:14:14.000000', NULL, 1),
(4719554, 679033, 89427, '<td valign="top">deffinatly meets the challenge</td>', 'deffinatly meets the challenge', '2008-05-23 11:15:14.000000', NULL, 1),
(4719556, 680383, 89426, '<td valign="top">Very nice structure in the picture</td>', 'Very nice structure in the picture', '2008-05-23 11:17:16.000000', NULL, 1),
