(4719561, 680215, 89426, '<td valign="top">I like this picture. Nice landscape in general</td>', 'I like this picture. Nice landscape in general', '2008-05-23 11:19:14.000000', NULL, 1),
(4719563, 680142, 89426, '<td valign="top">Nice model, cute picture</td>', 'Nice model, cute picture', '2008-05-23 11:20:04.000000', NULL, 1),
(4719564, 679760, 89426, '<td valign="top">Nice color in this photo</td>', 'Nice color in this photo', '2008-05-23 11:20:24.000000', NULL, 1),
(4719567, 680384, 89426, '<td valign="top">Nice color and detail</td>', 'Nice color and detail', '2008-05-23 11:21:15.000000', NULL, 1),
(4719611, 679199, 39679, '<td valign="top">I really like this shot but I honestly can''t tell you why.  It''s well exposed, really well lit and composed well but I can''t figure out why I''m enjoying a picture of sunglasses so much.</td>', 'I really like this shot but I honestly can''t tell you why.  It''s well exposed, really well lit and composed well but I can''t figure out why I''m enjoying a picture of sunglasses so much.', '2008-05-23 11:53:10.000000', NULL, 1),
(4719614, 680411, 39679, '<td valign="top">Cool shot.  It''s almost disturbing and I mean that in a good way.</td>', 'Cool shot.  It''s almost disturbing and I mean that in a good way.', '2008-05-23 11:54:44.000000', NULL, 1),
(4719615, 680523, 39679, '<td valign="top">Interesting shot but I''m finding my attention split between the well lit but small and less colorful pod and the brighter, bigger but not as promenant &lt;sp?&gt; flower.  I guess I''m saying that I''m having a hard time finding your intended subject.</td>', 'Interesting shot but I''m finding my attention split between the well lit but small and less colorful pod and the brighter, bigger but not as promenant <sp?> flower.  I guess I''m saying that I''m having a hard time finding your intended subject.', '2008-05-23 11:56:34.000000', NULL, 1),
(4719617, 680156, 39679, '<td valign="top">Water reflection shots are always cool.</td>', 'Water reflection shots are always cool.', '2008-05-23 11:57:07.000000', NULL, 1),
(4719618, 680534, 39679, '<td valign="top">Very sweet shot.  You''ve done a really good job capturing the fun that these ladies are having.</td>', 'Very sweet shot.  You''ve done a really good job capturing the fun that these ladies are having.', '2008-05-23 11:58:14.000000', NULL, 1),
(4719621, 680635, 39679, '<td valign="top">I''m guessing from, from the "stairs" that this is looking up a hill but, having shot it from the bottom you can''t really tell.  If you would have shot from photographer''s left you might have had a slightly better perspective to show the incline.  Just a thought</td>', 'I''m guessing from, from the "stairs" that this is looking up a hill but, having shot it from the bottom you can''t really tell.  If you would have shot from photographer''s left you might have had a slightly better perspective to show the incline.  Just a thought', '2008-05-23 12:00:10.000000', NULL, 1),
(4719625, 680607, 39679, '<td valign="top">I like the layout of this shot.  That said, your model gets a bit lost as a background object.  She''s small, in...well the background, and the slivers of light really draw your attention.  Perhaps having a light on your model might have given her more "importance" in the scene?</td>', 'I like the layout of this shot.  That said, your model gets a bit lost as a background object.  She''s small, in...well the background, and the slivers of light really draw your attention.  Perhaps having a light on your model might have given her more "importance" in the scene?', '2008-05-23 12:02:47.000000', NULL, 1),
(4719626, 680610, 39679, '<td valign="top">Nice use of natural lighting (at least it looks natural).</td>', 'Nice use of natural lighting (at least it looks natural).', '2008-05-23 12:03:18.000000', NULL, 1),
(4719627, 678784, 39679, '<td valign="top">I really like the slight lens flair on photographer''s left.  It really gives the feel of a back alley</td>', 'I really like the slight lens flair on photographer''s left.  It really gives the feel of a back alley', '2008-05-23 12:04:00.000000', NULL, 1),
(4719628, 679929, 39679, '<td valign="top">Great colors!</td>', 'Great colors!', '2008-05-23 12:04:21.000000', NULL, 1),
(4719631, 680319, 39679, '<td valign="top">Shots like these are hard to do.  With no real subject, it''s tough to give the viewer something to focus on.  I think you were going for the dappled light as a "texture" but if you could have isolated a specific leaf you might have had a better shot.</td>', 'Shots like these are hard to do.  With no real subject, it''s tough to give the viewer something to focus on.  I think you were going for the dappled light as a "texture" but if you could have isolated a specific leaf you might have had a better shot.', '2008-05-23 12:05:33.000000', NULL, 1),
(4719632, 679416, 39679, '<td valign="top">Cute shot and really well exposed.  Nice job</td>', 'Cute shot and really well exposed.  Nice job', '2008-05-23 12:06:11.000000', NULL, 1),
(4719637, 680227, 39679, '<td valign="top">Wow...that''s about as intense a blue as I''ve seen.  In fact, on my monitor at least, you may have managed too much contrast.  It''s a very intense shot though.</td>', 'Wow...that''s about as intense a blue as I''ve seen.  In fact, on my monitor at least, you may have managed too much contrast.  It''s a very intense shot though.', '2008-05-23 12:07:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4719638, 679445, 39679, '<td valign="top">Cute shot.  You''ve done a good job of not letting the lighting distract from your subject.</td>', 'Cute shot.  You''ve done a good job of not letting the lighting distract from your subject.', '2008-05-23 12:07:50.000000', NULL, 1),
(4719639, 680478, 39679, '<td valign="top">Great depth of field but the shot seems just a little out of focus to me.</td>', 'Great depth of field but the shot seems just a little out of focus to me.', '2008-05-23 12:08:12.000000', NULL, 1),
(4719643, 679664, 39679, '<td valign="top">This shot seems a bit dark to me but it looks like the scene had a lot of contrast making good exposure tough.</td>', 'This shot seems a bit dark to me but it looks like the scene had a lot of contrast making good exposure tough.', '2008-05-23 12:09:09.000000', NULL, 1),
(4719649, 679244, 39679, '<td valign="top">Great use of perspective!  It really makes this shot.  Please don''t take this wrong but if you''d have not shot this at ground level, the image would have had no interest but, as it is, it''s very nice shot.</td>', 'Great use of perspective!  It really makes this shot.  Please don''t take this wrong but if you''d have not shot this at ground level, the image would have had no interest but, as it is, it''s very nice shot.', '2008-05-23 12:10:37.000000', NULL, 1),
(4719650, 680571, 39679, '<td valign="top">It''s cool that you have two different patterns here and you managed awesome DOF.</td>', 'It''s cool that you have two different patterns here and you managed awesome DOF.', '2008-05-23 12:11:10.000000', NULL, 1),
(4719653, 680475, 39679, '<td valign="top">I''m sure there are lots of people that will point out that this shot has been done thousands of times before but you''ve done it very well.  Great shot!</td>', 'I''m sure there are lots of people that will point out that this shot has been done thousands of times before but you''ve done it very well.  Great shot!', '2008-05-23 12:11:47.000000', NULL, 1),
(4719654, 680475, 82503, '<td valign="top">Beautiful shot, the water looks very mystical. This will do well.</td>', 'Beautiful shot, the water looks very mystical. This will do well.', '2008-05-23 12:11:53.000000', NULL, 1),
(4719656, 679914, 39679, '<td valign="top">This is such a nice shot.  Including the out of focus flower as a background was a great idea and the lighting really adds a sense of calm to the image.</td>', 'This is such a nice shot.  Including the out of focus flower as a background was a great idea and the lighting really adds a sense of calm to the image.', '2008-05-23 12:12:37.000000', NULL, 1),
(4719661, 679697, 39679, '<td valign="top">great job of using the light to really put emphasis on your subject</td>', 'great job of using the light to really put emphasis on your subject', '2008-05-23 12:13:30.000000', NULL, 1),
(4719662, 679760, 39679, '<td valign="top">Great color saturation.  It''s all to easy to overdo color...especially when you have so much of one color.</td>', 'Great color saturation.  It''s all to easy to overdo color...especially when you have so much of one color.', '2008-05-23 12:14:21.000000', NULL, 1),
(4719666, 680215, 82503, '<td valign="top">The light is great, but the composition lacks something interesting. Maybe showing more of the creek in the lower part would have improved the image. Still, 8.</td>', 'The light is great, but the composition lacks something interesting. Maybe showing more of the creek in the lower part would have improved the image. Still, 8.', '2008-05-23 12:14:58.000000', NULL, 1),
(4719667, 680605, 39679, '<td valign="top">It doesn''t look like you desaturated this image...if that''s the case you did an outstanding job of setting up this shot.</td>', 'It doesn''t look like you desaturated this image...if that''s the case you did an outstanding job of setting up this shot.', '2008-05-23 12:14:58.000000', NULL, 1),
(4719668, 680532, 82503, '<td valign="top">Simple, but beautiful. Love it.</td>', 'Simple, but beautiful. Love it.', '2008-05-23 12:15:29.000000', NULL, 1),
(4719669, 680362, 39679, '<td valign="top">Good job in capturing the delicacy of these flowers.  I have to admit, though, that the spit but cocoon, to me, is really distracting.</td>', 'Good job in capturing the delicacy of these flowers.  I have to admit, though, that the spit but cocoon, to me, is really distracting.', '2008-05-23 12:15:40.000000', NULL, 1),
(4719671, 680384, 39679, '<td valign="top">Great shot.  Even though your subject is really small in the frame, putting her in red (complimentary to green) really forces the viewer''s eye to her.  nice shot.</td>', 'Great shot.  Even though your subject is really small in the frame, putting her in red (complimentary to green) really forces the viewer''s eye to her.  nice shot.', '2008-05-23 12:16:37.000000', NULL, 1),
(4719674, 680605, 82503, '<td valign="top">Beautiful shot. I like the composition and the fact that the flower stands out as the only colorful spot.</td>', 'Beautiful shot. I like the composition and the fact that the flower stands out as the only colorful spot.', '2008-05-23 12:17:36.000000', NULL, 1),
(4719680, 680137, 82503, '<td valign="top">Nice idea, something different from all the forest scenes. However, the expression looks a bit strained. "Have to hold my breath. Have to hold my breath."</td>', 'Nice idea, something different from all the forest scenes. However, the expression looks a bit strained. "Have to hold my breath. Have to hold my breath."', '2008-05-23 12:20:33.000000', NULL, 1),
(4719682, 680227, 82503, '<td valign="top">Wow, took me a moment to get over the confusion. Great shot!</td>', 'Wow, took me a moment to get over the confusion. Great shot!', '2008-05-23 12:21:43.000000', NULL, 1),
(4719684, 679646, 82503, '<td valign="top">The head of the girl on the right was cut off too high in my opinion. I think the image might have been better if her shoulders had been in it.</td>', 'The head of the girl on the right was cut off too high in my opinion. I think the image might have been better if her shoulders had been in it.', '2008-05-23 12:23:57.000000', NULL, 1),
(4719729, 680475, 42013, '<td valign="top">Pretty scene, exposed nicely. I feel that a touch more sharpening may have benefited you but that''s just my personal preference.</td>', 'Pretty scene, exposed nicely. I feel that a touch more sharpening may have benefited you but that''s just my personal preference.', '2008-05-23 12:56:25.000000', NULL, 1),
(4719863, 679877, 39679, '<td valign="top">I common "problem" is to include too much in a photo (literally everyone does it).  In this case, if you could have moved to photographer''s left and zoomed in the the irises with the stone wall in the background, I think you would have a wonderful shot.</td>', 'I common "problem" is to include too much in a photo (literally everyone does it).  In this case, if you could have moved to photographer''s left and zoomed in the the irises with the stone wall in the background, I think you would have a wonderful shot.', '2008-05-23 13:58:02.000000', NULL, 1),
(4719870, 679725, 39679, '<td valign="top">There are a lot of nice things about this shot but I think you tried to include too much.  There isn''t a clear point of interest.</td>', 'There are a lot of nice things about this shot but I think you tried to include too much.  There isn''t a clear point of interest.', '2008-05-23 13:59:01.000000', NULL, 1),
(4719873, 680142, 39679, '<td valign="top">Cool shot and nice lighting but I think you''re cropped a little to close.  It''s almost uncomfortable.</td>', 'Cool shot and nice lighting but I think you''re cropped a little to close.  It''s almost uncomfortable.', '2008-05-23 13:59:34.000000', NULL, 1),
(4719877, 680448, 39679, '<td valign="top">Wow...that''s a very calm bird</td>', 'Wow...that''s a very calm bird', '2008-05-23 14:00:29.000000', NULL, 1),
(4719884, 679627, 39679, '<td valign="top">Very well composed shot.</td>', 'Very well composed shot.', '2008-05-23 14:01:32.000000', NULL, 1),
(4719887, 679259, 39679, '<td valign="top">This is a very nice shot.  You''ve done a great job of selecting a background that doesn''t distract from your subject.</td>', 'This is a very nice shot.  You''ve done a great job of selecting a background that doesn''t distract from your subject.', '2008-05-23 14:02:26.000000', NULL, 1),
(4719889, 679081, 39679, '<td valign="top">Great job of framing your shot.</td>', 'Great job of framing your shot.', '2008-05-23 14:02:47.000000', NULL, 1),
(4719892, 680457, 39679, '<td valign="top">You have the makings of a really good shot here.  Cropping in so that the trees are on the edges of your shot would have removed that dock and bouy and really given the viewer something to focus on.</td>', 'You have the makings of a really good shot here.  Cropping in so that the trees are on the edges of your shot would have removed that dock and bouy and really given the viewer something to focus on.', '2008-05-23 14:04:10.000000', NULL, 1),
(4719895, 680441, 39679, '<td valign="top">Your shot really conveys a sense of calm.</td>', 'Your shot really conveys a sense of calm.', '2008-05-23 14:05:20.000000', NULL, 1),
(4719899, 680522, 39679, '<td valign="top">Great shot.  To me, by clearly showing the roses on a table, you''ve offered a sense of anticipation.  A decorated table is normally used for something...breakfast, dinner... and you''ve done a great job of conveying that.</td>', 'Great shot.  To me, by clearly showing the roses on a table, you''ve offered a sense of anticipation.  A decorated table is normally used for something...breakfast, dinner... and you''ve done a great job of conveying that.', '2008-05-23 14:07:19.000000', NULL, 1),
(4719902, 679524, 39679, '<td valign="top">Nice portrait.  I like the way you''ve put your subject on a dark background and  given the viewer something for him to "look" at (the lighter area on the left).</td>', 'Nice portrait.  I like the way you''ve put your subject on a dark background and  given the viewer something for him to "look" at (the lighter area on the left).', '2008-05-23 14:08:24.000000', NULL, 1),
(4719907, 679852, 39679, '<td valign="top">Your shot has the sense of having been "caught" or found which I really like and the warm light gives a sense of calm (the user doesn''t feel like he''s been caught doing something bad).</td>', 'Your shot has the sense of having been "caught" or found which I really like and the warm light gives a sense of calm (the user doesn''t feel like he''s been caught doing something bad).', '2008-05-23 14:09:59.000000', NULL, 1),
(4719908, 679460, 39679, '<td valign="top">Great use of DOF to really isolate your subject.</td>', 'Great use of DOF to really isolate your subject.', '2008-05-23 14:10:48.000000', NULL, 1),
(4719913, 680641, 39679, '<td valign="top">I can see that you''re trying to use DOF to isolate your subject but with all the "clutter", even out of focus, it''s hard to focus on the plant.</td>', 'I can see that you''re trying to use DOF to isolate your subject but with all the "clutter", even out of focus, it''s hard to focus on the plant.', '2008-05-23 14:11:38.000000', NULL, 1),
(4719916, 680137, 39679, '<td valign="top">It looks like your model is underwater?  No matter, you''ve managed some really interesting lighting.</td>', 'It looks like your model is underwater?  No matter, you''ve managed some really interesting lighting.', '2008-05-23 14:13:11.000000', NULL, 1),
(4719919, 679646, 39679, '<td valign="top">What great expressions and the warm colors (especially the red shirt) really forces the viewer''s eyes to your models.</td>', 'What great expressions and the warm colors (especially the red shirt) really forces the viewer''s eyes to your models.', '2008-05-23 14:13:57.000000', NULL, 1),
(4719926, 680621, 39679, '<td valign="top">Wow...amazing colors!  They really set this shot from so many others that explore buildings from street level.</td>', 'Wow...amazing colors!  They really set this shot from so many others that explore buildings from street level.', '2008-05-23 14:16:54.000000', NULL, 1),
(4719930, 680332, 39679, '<td valign="top">Interesting shot but (and this is going to sound really artsy), I''m having a hard time trying to get what you''re telling me in it.</td>', 'Interesting shot but (and this is going to sound really artsy), I''m having a hard time trying to get what you''re telling me in it.', '2008-05-23 14:17:46.000000', NULL, 1),
