(4721434, 680079, 93218, '<td valign="top">Beautiful colors and dapple effect very evident.</td>', 'Beautiful colors and dapple effect very evident.', '2008-05-24 13:15:49.000000', NULL, 1),
(4721435, 680479, 93218, '<td valign="top">This is one of my favorites!  Gorgeous.</td>', 'This is one of my favorites!  Gorgeous.', '2008-05-24 13:16:53.000000', NULL, 1),
(4721444, 680479, 76335, '<td valign="top">Nicely composed, great colors and focus. Doesn''t fully make use of a dappled light effect though.</td>', 'Nicely composed, great colors and focus. Doesn''t fully make use of a dappled light effect though.', '2008-05-24 14:02:31.000000', NULL, 1),
(4721483, 680018, 76335, '<td valign="top">Focus is too soft, and the dappled light isn''t to any great effect. Pose looks accidental. Keep trying though -- you have a great model there.</td>', 'Focus is too soft, and the dappled light isn''t to any great effect. Pose looks accidental. Keep trying though -- you have a great model there.', '2008-05-24 14:55:33.000000', NULL, 1),
(4721485, 680382, 76335, '<td valign="top">I''m surprised she can see the book. Nice idea -- obviously posed though, and much too dark.</td>', 'I''m surprised she can see the book. Nice idea -- obviously posed though, and much too dark.', '2008-05-24 14:57:00.000000', NULL, 1),
(4721490, 679373, 76335, '<td valign="top">Interesting study. Had to take some time to figure it out.</td>', 'Interesting study. Had to take some time to figure it out.', '2008-05-24 14:59:14.000000', NULL, 1),
(4721498, 680227, 76335, '<td valign="top">A great scene, but it seems overprocessed. Nice display of light.</td>', 'A great scene, but it seems overprocessed. Nice display of light.', '2008-05-24 15:02:25.000000', NULL, 1),
(4721536, 680537, 76335, '<td valign="top">Am interesting study and great effect, although the focus is a little mushy.</td>', 'Am interesting study and great effect, although the focus is a little mushy.', '2008-05-24 15:34:35.000000', NULL, 1),
(4721537, 680292, 76335, '<td valign="top">Original, nicely processed and a great effect.</td>', 'Original, nicely processed and a great effect.', '2008-05-24 15:35:33.000000', NULL, 1),
(4721550, 680410, 76335, '<td valign="top">Nice idea but the focus is a little soft and it doesn''t really show off dappled light to great effect.</td>', 'Nice idea but the focus is a little soft and it doesn''t really show off dappled light to great effect.', '2008-05-24 15:45:28.000000', NULL, 1),
(4721572, 678784, 76335, '<td valign="top">Interesting. Not sure what it has to do with dappled light.</td>', 'Interesting. Not sure what it has to do with dappled light.', '2008-05-24 15:49:34.000000', NULL, 1),
(4721578, 679551, 76335, '<td valign="top">Beautiful colors and brilliantly composed.</td>', 'Beautiful colors and brilliantly composed.', '2008-05-24 15:51:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4721581, 680082, 76335, '<td valign="top">Soft and busy with no real subject.</td>', 'Soft and busy with no real subject.', '2008-05-24 15:52:26.000000', NULL, 1),
(4721585, 679888, 76335, '<td valign="top">Too much processing and doesn''t hold the viewer''s attention. Maybe getting closer and somewhat under the trees would have helped.</td>', 'Too much processing and doesn''t hold the viewer''s attention. Maybe getting closer and somewhat under the trees would have helped.', '2008-05-24 15:54:34.000000', NULL, 1),
(4721590, 680657, 76335, '<td valign="top">It''s hard to figure out what this is (an animal obviously, but beyond that...) and I think you''re losing some of your viewers. Bringing more of your subject out of the shadows and/or composing or framing it differently would have helped.</td>', 'It''s hard to figure out what this is (an animal obviously, but beyond that...) and I think you''re losing some of your viewers. Bringing more of your subject out of the shadows and/or composing or framing it differently would have helped.', '2008-05-24 15:59:01.000000', NULL, 1),
(4721616, 680640, 90495, '<td valign="top">I''m having problems seeing the dappled light here. I know what you were seeing because I''ve experienced it myself. I just think the camera/lens didn''t pick up on it. Very nice shot of this calm lake though, serene and relaxing.</td>', 'I''m having problems seeing the dappled light here. I know what you were seeing because I''ve experienced it myself. I just think the camera/lens didn''t pick up on it. Very nice shot of this calm lake though, serene and relaxing.', '2008-05-24 16:20:53.000000', NULL, 1),
(4721620, 679674, 90495, '<td valign="top">Good adaptation of this challenge.</td>', 'Good adaptation of this challenge.', '2008-05-24 16:22:11.000000', NULL, 1),
(4721621, 680087, 90495, '<td valign="top">Dappled light on a grand scale. Very nice shot and fitting to the challenge.</td>', 'Dappled light on a grand scale. Very nice shot and fitting to the challenge.', '2008-05-24 16:23:04.000000', NULL, 1),
(4721625, 680292, 90495, '<td valign="top">Nice night shot.</td>', 'Nice night shot.', '2008-05-24 16:24:31.000000', NULL, 1),
(4721628, 680380, 90495, '<td valign="top">Woah, bad teeth!</td>', 'Woah, bad teeth!', '2008-05-24 16:25:24.000000', NULL, 1),
(4721631, 680422, 90495, '<td valign="top">More like shadows rather than dappled light I think. Or ...</td>', 'More like shadows rather than dappled light I think. Or ...', '2008-05-24 16:27:28.000000', NULL, 1),
(4721633, 680441, 90495, '<td valign="top">Yeah nice shot.</td>', 'Yeah nice shot.', '2008-05-24 16:27:44.000000', NULL, 1),
(4721635, 679539, 90495, '<td valign="top">Cool composition and the b&amp;w works for me.</td>', 'Cool composition and the b&w works for me.', '2008-05-24 16:28:18.000000', NULL, 1),
(4721637, 679498, 76335, '<td valign="top">A little too soft and the color balance doesn''t seem right.</td>', 'A little too soft and the color balance doesn''t seem right.', '2008-05-24 16:28:49.000000', NULL, 1),
(4721638, 679161, 90495, '<td valign="top">How many will survive? Good colours.</td>', 'How many will survive? Good colours.', '2008-05-24 16:29:23.000000', NULL, 1),
(4721639, 680466, 76335, '<td valign="top">Seems haphazardly composed, and the dappled light effect doesn''t really add anything.</td>', 'Seems haphazardly composed, and the dappled light effect doesn''t really add anything.', '2008-05-24 16:29:37.000000', NULL, 1),
(4721649, 679627, 76335, '<td valign="top">I''m not sure I get it. It''s an ordinary scene not enhanced by the dappled light. A good study maybe, but it doesn''t hold up well on its own.</td>', 'I''m not sure I get it. It''s an ordinary scene not enhanced by the dappled light. A good study maybe, but it doesn''t hold up well on its own.', '2008-05-24 16:35:13.000000', NULL, 1),
(4721654, 678739, 76335, '<td valign="top">The areas where the light falls on the guitar are overexposed; the areas in the shadows are mostly out of focus. Good idea though -- reminds me of outdoor summer concerts.</td>', 'The areas where the light falls on the guitar are overexposed; the areas in the shadows are mostly out of focus. Good idea though -- reminds me of outdoor summer concerts.', '2008-05-24 16:36:32.000000', NULL, 1),
(4721665, 679033, 76335, '<td valign="top">Nicely composed and potentially a nice scene, but the result is grainy and overexposed in places. A tricky shot for sure.</td>', 'Nicely composed and potentially a nice scene, but the result is grainy and overexposed in places. A tricky shot for sure.', '2008-05-24 16:41:03.000000', NULL, 1),
(4721666, 680475, 76335, '<td valign="top">Beautiful colors and nicely exposed.</td>', 'Beautiful colors and nicely exposed.', '2008-05-24 16:41:21.000000', NULL, 1),
(4721667, 679522, 76335, '<td valign="top">Great colors and emotion, but not a strong dapple effect. Arm''s a bit overexposed.</td>', 'Great colors and emotion, but not a strong dapple effect. Arm''s a bit overexposed.', '2008-05-24 16:41:56.000000', NULL, 1),
(4721668, 680096, 76335, '<td valign="top">Nice effect, but the dapple doesn''t add much to the image. Looks a little too posed also.</td>', 'Nice effect, but the dapple doesn''t add much to the image. Looks a little too posed also.', '2008-05-24 16:41:58.000000', NULL, 1),
(4721682, 679641, 76335, '<td valign="top">Interesting abstract and warm tones.</td>', 'Interesting abstract and warm tones.', '2008-05-24 16:52:19.000000', NULL, 1),
(4721684, 680617, 76335, '<td valign="top">Contrast is a little high, but a dramatic effect and "cute" (for lack of a better word right now) pose.</td>', 'Contrast is a little high, but a dramatic effect and "cute" (for lack of a better word right now) pose.', '2008-05-24 16:52:27.000000', NULL, 1),
(4721685, 680137, 76335, '<td valign="top">Underwater? Wow. Points for creativity.</td>', 'Underwater? Wow. Points for creativity.', '2008-05-24 16:52:29.000000', NULL, 1),
(4721686, 680149, 76335, '<td valign="top">A great study in dappled light and shadows. A little hot in places and it seems crooked, but you''ve captured the stillness of the library quite well.</td>', 'A great study in dappled light and shadows. A little hot in places and it seems crooked, but you''ve captured the stillness of the library quite well.', '2008-05-24 16:52:34.000000', NULL, 1),
(4721687, 679928, 76335, '<td valign="top">Good idea. The thing in the middle is distracting so long as the viewer can''t figure out what it is (a wagon wheel?). Anyway, a nice study in dappled light.</td>', 'Good idea. The thing in the middle is distracting so long as the viewer can''t figure out what it is (a wagon wheel?). Anyway, a nice study in dappled light.', '2008-05-24 16:52:36.000000', NULL, 1),
(4721688, 680142, 52549, '<td valign="top">Beautiful image of a Lovely little girl. Hope this does well for you.</td>', 'Beautiful image of a Lovely little girl. Hope this does well for you.', '2008-05-24 16:53:09.000000', NULL, 1),
(4721689, 679107, 76335, '<td valign="top">Too bad about the errant vine/branch. Otherwise, not a bad shot.</td>', 'Too bad about the errant vine/branch. Otherwise, not a bad shot.', '2008-05-24 16:53:37.000000', NULL, 1),
